-- mod-dnd: the endgame (generated by tools/endgame.py)

-- lair actions: a boss's home acts at the top of each round (DndEndgame.cpp, DndCombat.cpp LairRound)
DROP TABLE IF EXISTS `dnd_lair`;
CREATE TABLE `dnd_lair` (
  `encounter_id` INT UNSIGNED NOT NULL,
  `idx` TINYINT UNSIGNED NOT NULL,
  `kind` VARCHAR(8) NOT NULL,
  `name` VARCHAR(64) NOT NULL,
  `text` VARCHAR(255) NOT NULL DEFAULT '',
  `dice` VARCHAR(16) NOT NULL DEFAULT '',
  `dmg_type` VARCHAR(16) NOT NULL DEFAULT 'Necrotic',
  `save_abil` VARCHAR(4) NOT NULL DEFAULT 'DEX',
  `dc` TINYINT NOT NULL DEFAULT 13,
  `radius` FLOAT NOT NULL DEFAULT 3,
  `entry` INT UNSIGNED NOT NULL DEFAULT 0,
  `most` TINYINT UNSIGNED NOT NULL DEFAULT 2,
  `stop` VARCHAR(48) NOT NULL DEFAULT '',
  PRIMARY KEY (`encounter_id`, `idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- what endgame encounters pay instead of XP (first clear): items, coin (copper), a title (CharTitles.dbc)
DROP TABLE IF EXISTS `dnd_encounter_reward`;
CREATE TABLE `dnd_encounter_reward` (
  `encounter_id` INT UNSIGNED NOT NULL,
  `item` INT UNSIGNED NOT NULL DEFAULT 0,
  `count` INT UNSIGNED NOT NULL DEFAULT 1,
  `money` INT UNSIGNED NOT NULL DEFAULT 0,
  `title` INT UNSIGNED NOT NULL DEFAULT 0,
  KEY `encounter_id` (`encounter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- portal keepers' destinations
DROP TABLE IF EXISTS `dnd_portal`;
CREATE TABLE `dnd_portal` (
  `entry` INT UNSIGNED NOT NULL,
  `idx` TINYINT UNSIGNED NOT NULL,
  `label` VARCHAR(64) NOT NULL,
  `say` VARCHAR(255) NOT NULL DEFAULT '',
  `map` INT UNSIGNED NOT NULL,
  `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL, `o` FLOAT NOT NULL,
  `zone` INT UNSIGNED NOT NULL DEFAULT 0,
  `level` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`entry`, `idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- elixirs (their effects are dnd_item_effect rows, like the magic items')
DROP TABLE IF EXISTS `dnd_elixir`;
CREATE TABLE `dnd_elixir` (
  `spell` INT UNSIGNED NOT NULL,
  `item` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `spell_script_names` WHERE `ScriptName` = 'spell_dnd_elixir';

