INSERT INTO `dnd_lair` VALUES
(222, 1, 'burst', 'Banshee''s Wail', 'The queen''s grief takes a voice of its own, and the dais rings with it.', '2d8', 'Psychic', 'WIS', 15, 4.0, 0, 0, ''),
(222, 2, 'burst', 'Plague Vents', 'Grates in the floor cough green: the Apothecarium''s breath, piped up to the throne.', '3d6', 'Poison', 'CON', 15, 3.0, 0, 0, 'cleared:218'),
(222, 3, 'grip', 'Grasping Dead', 'Cold hands come up through the flagstones, the city''s unburied, and they hold on.', '', 'Necrotic', 'STR', 15, 3.0, 0, 0, 'found:lordaeron_ash'),
(222, 4, 'call', 'The Queen''s Guard', 'A door in the dark opens, and a Royal Dreadguard steps through.', '', 'Slashing', 'DEX', 0, 0.0, 13839, 2, 'cleared:212'),
(218, 1, 'burst', 'Boiling Vats', 'A vat of half-made plague boils over, and the floor runs green.', '2d6', 'Poison', 'CON', 13, 3.0, 0, 0, ''),
(218, 2, 'call', 'The Experiment', 'Something lurches out of a cage at the back.', '', 'Slashing', 'DEX', 0, 0.0, 17895, 1, ''),
(236, 1, 'burst', 'Thunder of Hooves', 'The lodge floor shakes as if a herd were running under it, and the boards jump.', '2d8', 'Thunder', 'DEX', 15, 4.0, 0, 0, ''),
(236, 2, 'burst', 'Grimtotem Venom', 'A clay pot of Magatha''s brewing cracks in the fire, and the smoke is green.', '3d6', 'Poison', 'CON', 15, 3.0, 0, 0, 'cleared:232'),
(236, 3, 'call', 'War Drums', 'The war drums sound from the rise below, and an Honor Guard answers them.', '', 'Slashing', 'DEX', 0, 0.0, 3083, 2, 'cleared:234'),
(236, 4, 'grip', 'Mesa Gale', 'A gale comes howling off the edge of the mesa and pins whoever it catches.', '', 'Thunder', 'STR', 15, 3.0, 0, 0, 'found:stillwind_totem'),
(251, 1, 'burst', 'Doomhammer''s Thunder', 'The Warchief''s hammer strikes the floor of the hold, and the thunder rolls outward.', '2d8', 'Thunder', 'DEX', 15, 4.0, 0, 0, ''),
(251, 2, 'burst', 'Chain Lightning', 'The spirits of the storm answer the Warchief''s call, and lightning leaps across the hold.', '3d6', 'Lightning', 'DEX', 15, 3.0, 0, 0, 'cleared:249'),
(251, 3, 'call', 'The Kor''kron Answer', 'Boots on the stair: a Kor''kron Elite runs in to stand by his Warchief.', '', 'Slashing', 'DEX', 0, 0.0, 14304, 2, 'cleared:246'),
(251, 4, 'burst', 'Fel Fire', 'Green fire licks up from a brazier no orc lit - the Burning Blade''s gift to the hold.', '3d6', 'Fire', 'DEX', 15, 3.0, 0, 0, 'cleared:240'),
(251, 5, 'grip', 'Earthquake', 'The earth under Grommash Hold heaves and cracks, and holds whoever stands on it.', '', 'Bludgeoning', 'STR', 15, 4.0, 0, 0, 'found:earthmother_stone');
