INSERT INTO `dnd_portal` VALUES
(9102001, 1, 'The Undercity', 'Lordaeron''s capital, under the ruins - the Banshee Queen''s city. Mind your breath down there; they notice it.', 0, 1791.0, 127.5, -63.76, 1.1, 17, 6),
(9102001, 2, 'Thunder Bluff', 'The tauren''s mesas, high over Mulgore. Their chieftain is an honourable bull - but someone has been telling him lies about you.', 1, -1255.5, 28.0, 128.3, 1.6, 19, 6),
(9102001, 3, 'Orgrimmar', 'The Warchief''s city. If you go there, go ready - it''s the heart of the Horde, and it will fight like one.', 1, 1624.8, -4371.5, 12.2, 2.3, 20, 6),
(9102002, 1, 'Stormwind', 'Home, then. Try not to bring anything back with you.', 0, -9003.0, 846.0, 105.95, 0.8, 0, 1),
(9102003, 1, 'Stormwind', 'Home. Mind the step - the mesa''s a long way down.', 0, -9003.0, 846.0, 105.95, 0.8, 0, 1),
(9102004, 1, 'Stormwind', 'Home, and quickly. The grunts have started noticing me.', 0, -9003.0, 846.0, 105.95, 0.8, 0, 1);
